import{_ as e,V as a,W as l,a0 as i}from"./framework-9a29aaa0.js";const s={},t=i('<p>线性一致性</p><p>有些论文提到了强一致性，它基本等同于线性一致性。</p><p><strong>线性一致性</strong>的描述的是一个分布式系统表现的就像只有一台服务器一样(假设其不会崩溃)，该服务器可以按照顺序逐一执行客户端请求，且期间没有任何异常情况发生时的行为。</p><p>其定义如下：</p><ul><li>客户端的一系列请求构成一个执行历史，执行历史整体可以按照一个顺序排列，要求排列顺序与客户端的实际时间相符合。</li><li>对于非并发请求(在时间上没有重叠的请求)，其先后顺序已经确定的，要求排列顺序不能与这些确定的顺序冲突。例如所以如果一个客户端发送请求并收到响应，随后在某个时间点，另一个客户端发送请求并收到响应，那么这两个请求时有序的，因为其中一个是在另一个完成后开始的，所以它是线性化的。(happen-before关系)</li><li>每个读操作都能看到最近一次对该同一个数据进行写入之后的值。</li></ul><p>这里的定义相对而言是抽象的，后续会使用例子进行讲解。</p><h2 id="ps" tabindex="-1"><a class="header-anchor" href="#ps" aria-hidden="true">#</a> PS</h2><h3 id="线性一致性和顺序一致性的区别是什么" tabindex="-1"><a class="header-anchor" href="#线性一致性和顺序一致性的区别是什么" aria-hidden="true">#</a> 线性一致性和顺序一致性的区别是什么？</h3><ul><li>线性一致性：更关注全局时间下的执行顺序（多个进程之间各个操作的执行顺序）</li><li>顺序一致性：更关注单个进程的执行顺序，即：对于顺序一致性，任何执行的结果与所有处理器的操作以某种顺序执行的结果相同，并且每个处理器的操作按照其程序指定的顺序出现在这个序列中。</li></ul>',9),r=[t];function n(o,c){return a(),l("div",null,r)}const p=e(s,[["render",n],["__file","lesson7.html.vue"]]);export{p as default};
